beforeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class MyClass {
    public boolean checkWindows() {
        return Platform.getOS().equals(Platform.OS_WIN32);
    }

    public void otherMethod() {
        String os = Platform.getOS(); // Should not be affected
    }
}

afterExample:
package test;

import org.eclipse.core.runtime.Platform;

public class MyClass {
    public boolean checkWindows() {
        return Platform.OS.isWindows();
    }

    public void otherMethod() {
        String os = Platform.getOS(); // Should not be affected
    }
}

negativeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class MyClass {
    public boolean checkOtherOS(String osName) {
        // This should not match, as it uses a variable for comparison
        return Platform.getOS().equals(osName);
    }

    public boolean checkLinux() {
        // This should not match, as it's a different OS constant
        return Platform.getOS().equals(Platform.OS_LINUX);
    }

    public String getOsName() {
        // This should not match, as it's not an equals call
        return Platform.getOS();
    }
}
